macro_rules! cached_env_present {
    ($fn_name:ident, $name:literal) => {
        #[inline]
        fn $fn_name() -> bool {
            static ENABLED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
            *ENABLED.get_or_init(|| std::env::var_os($name).is_some())
        }
    };
}

