fn blend_forced_off_for_fs_config(fs_addr: u64, global: bool, targets: &[u64]) -> bool {
    global || targets.contains(&fs_addr)
}

fn blend_forced_off_for_fs(fs_addr: u64) -> bool {
    static TARGETS: std::sync::OnceLock<Vec<u64>> = std::sync::OnceLock::new();
    blend_forced_off_for_fs_config(
        fs_addr,
        blend_forced_off(),
        TARGETS.get_or_init(|| parse_env_u64_list("NEXIUM_NO_BLEND_FS")),
    )
}

fn mask_mrt_for_fs_texture(fs_addr: u64, texture_gpu_va: u64) -> bool {
    static TARGET: std::sync::OnceLock<Option<(u64, u64)>> = std::sync::OnceLock::new();
    TARGET
        .get_or_init(|| {
            let value = std::env::var("NEXIUM_MASK_MRT_FS_TEXTURE").ok()?;
            let (fs, texture) = value.split_once(':')?;
            Some((parse_env_u64(fs.trim())?, parse_env_u64(texture.trim())?))
        })
        .is_some_and(|(target_fs, target_texture)| {
            fs_addr == target_fs && texture_gpu_va == target_texture
        })
}

#[derive(Debug)]
struct GraphicsSpirvEnvironmentConfig {
    debug_targets: Option<Vec<u64>>,
    debug_fingerprint: u128,
    production_fingerprint: u128,
}

fn graphics_spirv_environment_config() -> &'static GraphicsSpirvEnvironmentConfig {
    static CONFIG: std::sync::OnceLock<GraphicsSpirvEnvironmentConfig> = std::sync::OnceLock::new();
    CONFIG.get_or_init(|| {
        let debug_targets = std::env::var_os("NEXIUM_FS_DEBUG_TARGET").map(|value| {
            value
                .to_string_lossy()
                .split(',')
                .filter_map(|part| parse_env_u64(part.trim()))
                .collect()
        });
        GraphicsSpirvEnvironmentConfig {
            debug_targets,
            debug_fingerprint: nexium_spirv::graphics_spirv_environment_fingerprint(true),
            production_fingerprint: nexium_spirv::graphics_spirv_environment_fingerprint(false),
        }
    })
}

fn graphics_spirv_environment_for_fs(fs_addr: u64) -> (bool, u128) {
    let config = graphics_spirv_environment_config();
    let debug_active = config
        .debug_targets
        .as_ref()
        .map_or(true, |targets| targets.contains(&fs_addr));
    let fingerprint = if debug_active {
        config.debug_fingerprint
    } else {
        config.production_fingerprint
    };
    (debug_active, fingerprint)
}

fn elapsed_ms(start: std::time::Instant) -> f64 {
    start.elapsed().as_secs_f64() * 1000.0
}

fn next_gpu_op_seq() -> u64 {
    use std::sync::atomic::{AtomicU64, Ordering};
    static GPU_OP_SEQ: AtomicU64 = AtomicU64::new(0);
    GPU_OP_SEQ.fetch_add(1, Ordering::Relaxed)
}

fn unimplemented_samples(cfg: &nexium_shader::Cfg) -> Vec<String> {
    let mut samples = Vec::new();
    for block in &cfg.blocks {
        for inst in &block.program.instructions {
            if let nexium_shader::IrOp::Unimplemented { opcode, raw } = inst.op {
                samples.push(format!("{:?}:{:#x}", opcode, raw));
                if samples.len() >= 8 {
                    return samples;
                }
            }
        }
    }
    samples
}

fn graphics_cfg_has_unimplemented(cfg: &nexium_shader::Cfg) -> bool {
    cfg.unimplemented != 0
        || cfg.blocks.iter().any(|block| {
            block
                .program
                .instructions
                .iter()
                .any(|inst| matches!(&inst.op, nexium_shader::IrOp::Unimplemented { .. }))
        })
}

fn known_cbuf_index_bits(
    value: nexium_shader::IrValue,
    defs: &std::collections::HashMap<u32, &nexium_shader::IrInst>,
    depth: u8,
) -> Option<u32> {
    if depth >= 24 {
        return None;
    }
    let resolve = |value| known_cbuf_index_bits(value, defs, depth + 1);
    match value {
        nexium_shader::IrValue::Zero => Some(0),
        nexium_shader::IrValue::ImmU32(value) => Some(value),
        nexium_shader::IrValue::ImmF32(value) => Some(value.to_bits()),
        nexium_shader::IrValue::GprIn(_) => None,
        nexium_shader::IrValue::Inst(value) => {
            let inst = defs.get(&value.0)?;
            if inst.pred.is_some() {
                return None;
            }
            match &inst.op {
                nexium_shader::IrOp::Mov(value) => resolve(*value),
                nexium_shader::IrOp::IAdd { a, b, neg_a, neg_b } => {
                    let mut a = resolve(*a)?;
                    let mut b = resolve(*b)?;
                    if *neg_a {
                        a = 0u32.wrapping_sub(a);
                    }
                    if *neg_b {
                        b = 0u32.wrapping_sub(b);
                    }
                    Some(a.wrapping_add(b))
                }
                nexium_shader::IrOp::IMul { a, b } => Some(resolve(*a)?.wrapping_mul(resolve(*b)?)),
                nexium_shader::IrOp::IScAdd {
                    a,
                    b,
                    shift,
                    neg_a,
                    neg_b,
                } => {
                    let mut a = resolve(*a)?;
                    let mut b = resolve(*b)?;
                    if *neg_a {
                        a = 0u32.wrapping_sub(a);
                    }
                    if *neg_b {
                        b = 0u32.wrapping_sub(b);
                    }
                    Some(a.wrapping_shl(u32::from(*shift)).wrapping_add(b))
                }
                _ => None,
            }
        }
    }
}

fn collect_cbuf_reads(cfg: &nexium_shader::Cfg, stage_base: u32) -> Vec<CbufRead> {
    let defs = cfg
        .blocks
        .iter()
        .flat_map(|block| &block.program.instructions)
        .filter_map(|inst| inst.result.map(|result| (result.0, inst)))
        .collect::<std::collections::HashMap<_, _>>();
    let mut reads = Vec::new();
    for block in &cfg.blocks {
        for inst in &block.program.instructions {
            match inst.op {
                nexium_shader::IrOp::LoadCbuf {
                    binding,
                    byte_offset,
                } => reads.push(CbufRead {
                    logical_slot: (stage_base + u32::from(binding)) as u8,
                    byte_offset,
                    index_origin: CbufIndexOrigin::Static,
                }),
                nexium_shader::IrOp::LoadCbufIndexed {
                    binding,
                    byte_offset,
                    index,
                    ..
                } => reads.push(CbufRead {
                    logical_slot: (stage_base + u32::from(binding)) as u8,
                    byte_offset,
                    index_origin: known_cbuf_index_bits(index, &defs, 0)
                        .map(CbufIndexOrigin::Constant)
                        .unwrap_or_else(|| match index {
                            nexium_shader::IrValue::GprIn(register) => {
                                CbufIndexOrigin::Gpr(register)
                            }
                            nexium_shader::IrValue::Inst(value) => {
                                CbufIndexOrigin::Instruction(value.0)
                            }
                            nexium_shader::IrValue::Zero
                            | nexium_shader::IrValue::ImmU32(_)
                            | nexium_shader::IrValue::ImmF32(_) => {
                                unreachable!("immediate cbuf indices are always known")
                            }
                        }),
                }),
                nexium_shader::IrOp::LoadStorage {
                    cbuf_binding,
                    cbuf_offset,
                    ..
                } => {
                    for byte_offset in [cbuf_offset, cbuf_offset.wrapping_add(4)] {
                        reads.push(CbufRead {
                            logical_slot: (stage_base + u32::from(cbuf_binding)) as u8,
                            byte_offset,
                            index_origin: CbufIndexOrigin::Static,
                        });
                    }
                }
                _ => {}
            }
        }
    }
    reads.sort_unstable();
    reads.dedup();
    reads
}

fn collect_graphics_cbuf_reads(
    vs_cfg: &nexium_shader::Cfg,
    fs_cfg: &nexium_shader::Cfg,
) -> Vec<CbufRead> {
    let mut reads = collect_cbuf_reads(vs_cfg, 0);
    reads.extend(collect_cbuf_reads(fs_cfg, FRAGMENT_CBUF_BASE as u32));
    reads.sort_unstable();
    reads.dedup();
    reads
}

fn packed_cbuf_slot(data: &[u8], logical_slot: usize) -> Option<&[u8]> {
    if logical_slot >= PACKED_CBUF_SLOTS {
        return None;
    }
    let directory = logical_slot.checked_mul(8)?;
    let base_word = u32::from_le_bytes(data.get(directory..directory + 4)?.try_into().ok()?);
    let word_count = u32::from_le_bytes(data.get(directory + 4..directory + 8)?.try_into().ok()?);
    if word_count == 0 {
        return Some(&[]);
    }
    let start = usize::try_from(base_word).ok()?.checked_mul(4)?;
    let len = usize::try_from(word_count).ok()?.checked_mul(4)?;
    let end = start.checked_add(len)?;
    data.get(start..end)
}

fn packed_cbuf_word(data: &[u8], logical_slot: usize, byte_offset: usize) -> Option<u32> {
    let slot = packed_cbuf_slot(data, logical_slot)?;
    let bytes = slot.get(byte_offset..byte_offset.checked_add(4)?)?;
    Some(u32::from_le_bytes(bytes.try_into().ok()?))
}

const AURORA_VERTEX_BUFFER_SIZE: u32 = 3 * 1024 * 1024;
const AURORA_STORAGE_BUFFER_SIZE: u32 = 8 * 1024 * 1024;

fn is_aurora_fixed_ssbo(desc: nexium_shader::StorageBufferAddr, descriptor_size: u32) -> bool {
    desc.is_direct()
        && desc.cbuf_binding == 2
        && matches!(
            (desc.cbuf_offset, descriptor_size),
            (0x00, AURORA_VERTEX_BUFFER_SIZE) | (0x10, AURORA_STORAGE_BUFFER_SIZE)
        )
}

fn ssbo_snapshot_window(
    desc: nexium_shader::StorageBufferAddr,
    descriptor_size: u32,
    alignment_slack: usize,
    logical_size: usize,
    sparse_window: Option<(usize, usize)>,
) -> (usize, usize) {
    static FULL_ARENA_DISABLED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
    let full_arena_disabled = *FULL_ARENA_DISABLED
        .get_or_init(|| std::env::var_os("NEXIUM_NO_FULL_SSBO_CACHE").is_some());
    if !full_arena_disabled && alignment_slack == 0 && is_aurora_fixed_ssbo(desc, descriptor_size) {
        (0, logical_size)
    } else {
        sparse_window.unwrap_or((0, logical_size))
    }
}

fn aurora_ssbo_read_window(
    desc: nexium_shader::StorageBufferAddr,
    descriptor_size: u32,
    cbuf_data: &GraphicsCbufPayload,
    cbuf_reads: &[CbufRead],
    first_vertex: u32,
    vertex_count: u32,
) -> Option<(usize, usize)> {
    if !desc.is_direct() || desc.cbuf_binding != 2 {
        return None;
    }

    let size = descriptor_size as usize;
    let align = desc.align.max(1) as usize;
    let align_down = |value: usize| value & !(align - 1);
    match (desc.cbuf_offset, descriptor_size) {
        (0x00, AURORA_VERTEX_BUFFER_SIZE) => {
            let start = cbuf_data.word(1, 0)? as usize;
            if start >= size {
                return None;
            }
            let vertices = first_vertex.saturating_add(vertex_count.max(1)) as usize;
            let end = start
                .saturating_add(vertices.saturating_mul(256))
                .saturating_add(16)
                .min(size);
            let start = align_down(start);
            Some((start, end.saturating_sub(start).max(16)))
        }
        (0x10, AURORA_STORAGE_BUFFER_SIZE) => {
            let mut starts = cbuf_reads
                .iter()
                .filter_map(|read| {
                    let offset = read.effective_byte_offset()?;
                    (read.logical_slot == 1 && (0x20..0x50).contains(&offset))
                        .then(|| cbuf_data.word(1, offset as usize))
                        .flatten()
                })
                .map(|value| value as usize)
                .filter(|value| *value < size)
                .collect::<Vec<_>>();
            starts.sort_unstable();
            starts.dedup();
            let start = align_down(*starts.first()?);
            let end = starts
                .last()?
                .saturating_add(3 * 1024 * 1024)
                .saturating_add(16)
                .min(size);
            Some((start, end.saturating_sub(start).max(16)))
        }
        _ => None,
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct ResolvedStorageBufferDescriptor {
    actual_base: u64,
    descriptor_size: u32,
    direct_descriptor: Option<[u8; 16]>,
}

fn read_storage_descriptor_bytes(
    mappings: &GpuMappings,
    mem_read: &dyn Fn(u64, &mut [u8]) -> bool,
    gpu_va: u64,
    len: usize,
) -> Option<Vec<u8>> {
    read_gpu_strict(mappings, mem_read, gpu_va, len).or_else(|| {
        let (_, cpu, remaining) = mappings.cpu_address_for_any32(gpu_va)?;
        if remaining < len as u64 {
            return None;
        }
        let mut data = vec![0u8; len];
        mem_read(cpu, &mut data).then_some(data)
    })
}

fn resolve_storage_buffer_descriptor(
    descriptor_index: usize,
    descriptor: nexium_shader::StorageBufferAddr,
    direct_cbuf_va: u64,
    resolved_actual_bases: &[Option<u64>],
    mappings: &GpuMappings,
    mem_read: &dyn Fn(u64, &mut [u8]) -> bool,
) -> Option<ResolvedStorageBufferDescriptor> {
    if let Some(indirect) = descriptor.indirect {
        let parent_index = indirect.parent_buffer_index as usize;
        if parent_index >= descriptor_index {
            return None;
        }
        let parent_base = resolved_actual_bases.get(parent_index).copied().flatten()?;
        let pointer_va = parent_base.checked_add(u64::from(indirect.pointer_offset))?;
        let bytes = read_storage_descriptor_bytes(mappings, mem_read, pointer_va, 8)?;
        let actual_base = u64::from_le_bytes(bytes.try_into().ok()?);
        (actual_base != 0).then_some(ResolvedStorageBufferDescriptor {
            actual_base,
            descriptor_size: descriptor.required_size.max(16),
            direct_descriptor: None,
        })
    } else {
        if direct_cbuf_va == 0 {
            return None;
        }
        let descriptor_va = direct_cbuf_va.checked_add(u64::from(descriptor.cbuf_offset))?;
        let bytes = read_storage_descriptor_bytes(mappings, mem_read, descriptor_va, 16)?;
        let direct_descriptor: [u8; 16] = bytes.try_into().ok()?;
        let actual_base = u64::from_le_bytes(direct_descriptor[0..8].try_into().ok()?);
        let descriptor_size = u32::from_le_bytes(direct_descriptor[8..12].try_into().ok()?);
        (actual_base != 0).then_some(ResolvedStorageBufferDescriptor {
            actual_base,
            descriptor_size,
            direct_descriptor: Some(direct_descriptor),
        })
    }
}

fn storage_pointer_source_mask(descriptors: &[nexium_shader::StorageBufferAddr]) -> Vec<bool> {
    let mut sources = vec![false; descriptors.len()];
    for descriptor in descriptors {
        if let Some(indirect) = descriptor.indirect {
            if let Some(is_source) = sources.get_mut(indirect.parent_buffer_index as usize) {
                *is_source = true;
            }
        }
    }
    sources
}

