    #[test]
    fn configured_color_rt_comparison_uses_slot_format_and_live_identity() {
        let rt = nexium_gpu::draw::ConfiguredColorRt {
            raw_slot: 2,
            key: RtKey::new(7, 64, 64, 0x50_000).with_mapping_epoch(11),
            format: vk::Format::R16_SFLOAT,
        };
        assert!(super::same_live_configured_color_rts(&[rt], &[rt]));

        let mut changed = rt;
        changed.raw_slot = 1;
        assert!(!super::same_live_configured_color_rts(&[rt], &[changed]));
        changed = rt;
        changed.format = vk::Format::R16_UNORM;
        assert!(!super::same_live_configured_color_rts(&[rt], &[changed]));
        changed = rt;
        changed.key.mapping_epoch += 1;
        assert!(!super::same_live_configured_color_rts(&[rt], &[changed]));
    }

    #[test]
    fn census_fold_ring_detects_repeats_and_evicts() {
        assert_eq!(
            super::census_fold(super::CENSUS_FOLD_SEED, 7),
            super::census_fold(super::CENSUS_FOLD_SEED, 7)
        );
        assert_ne!(
            super::census_fold(super::CENSUS_FOLD_SEED, 7),
            super::census_fold(super::CENSUS_FOLD_SEED, 9)
        );
        let mut ring = super::CensusFoldRing::new();
        let fold = super::census_fold(super::CENSUS_FOLD_SEED, 7);
        assert!(!ring.probe(fold));
        assert!(ring.probe(fold));
        for value in 1000..1064u64 {
            ring.probe(super::census_fold(super::CENSUS_FOLD_SEED, value));
        }
        assert!(!ring.probe(fold));
        assert!(!ring.probe(0));
        assert!(!ring.probe(0));
    }

