    #[test]
    fn small_rt_guest_write_crosses_mappings_and_retains_partial_failure() {
        let mut mappings = crate::gpu::GpuMappings::new();
        mappings.add(0x1000, 4, 0x20_000, 1);
        mappings.add(0x1004, 4, 0x30_000, 1);
        mappings.add(0x9000, 4, 0x20_000, 2);
        let expected_chunks = vec![
            GuestWriteChunk {
                gpu_va: 0x1002,
                cpu_addr: 0x20_002,
                data_offset: 0,
                len: 2,
            },
            GuestWriteChunk {
                gpu_va: 0x1004,
                cpu_addr: 0x30_000,
                data_offset: 2,
                len: 4,
            },
        ];
        assert_eq!(
            plan_guest_write_chunks(&mappings, 0x1002, 6),
            Some(expected_chunks.clone())
        );

        let writes = std::sync::Mutex::new(Vec::new());
        let complete = write_guest_strict(
            &mappings,
            &|cpu, bytes| {
                writes.lock().unwrap().push((cpu, bytes.to_vec()));
                true
            },
            0x1002,
            &[1, 2, 3, 4, 5, 6],
        );
        assert!(complete.complete);
        assert_eq!(complete.written, expected_chunks);
        assert_eq!(
            *writes.lock().unwrap(),
            vec![(0x20_002, vec![1, 2]), (0x30_000, vec![3, 4, 5, 6])]
        );
        assert!(
            guest_write_alias_ranges(&mappings, &complete.written).contains(&GuestRange {
                start: 0x9002,
                end: 0x9004,
            })
        );

        let failed = write_guest_strict(
            &mappings,
            &|cpu, _| cpu != 0x30_000,
            0x1002,
            &[1, 2, 3, 4, 5, 6],
        );
        assert!(!failed.complete);
        assert_eq!(failed.written, expected_chunks[..1]);
    }

    #[test]
    fn cube_dependency_ranges_cover_every_face_and_mip_without_touching_next_cube() {
        let base = 0x5689_d0000u64;
        let layer_stride = 0x2c000u64;
        let ranges = normalize_guest_ranges(vec![
            GuestRange {
                start: base + layer_stride,
                end: base + layer_stride * 4,
            },
            GuestRange {
                start: base,
                end: base + layer_stride * 2,
            },
            GuestRange {
                start: base + layer_stride * 4,
                end: base + layer_stride * 6,
            },
        ]);
        assert_eq!(
            ranges,
            vec![GuestRange {
                start: base,
                end: base + layer_stride * 6,
            }]
        );

        for face in 0..6u64 {
            let face_key =
                nexium_gpu::rt_cache::RtKey::new(168, 128, 128, base + face * layer_stride);
            assert!(small_rt_starts_in_ranges(face_key, &ranges));

            let mip_key =
                nexium_gpu::rt_cache::RtKey::new(168, 32, 32, base + face * layer_stride + 0x28000);
            assert!(small_rt_starts_in_ranges(mip_key, &ranges));
        }

        let next_cube = nexium_gpu::rt_cache::RtKey::new(169, 128, 128, base + layer_stride * 6);
        assert!(!small_rt_starts_in_ranges(next_cube, &ranges));
    }

    #[test]
    fn graphics_ring_chunks_never_exceed_the_safe_multi_draw_budget() {
        let safe = nexium_gpu::renderer::GRAPHICS_RING_SAFE_BATCH_BYTES;
        let capacity = nexium_gpu::renderer::GRAPHICS_RING_CAPACITY_BYTES;
        let unit = safe / 8;
        let costs = [3 * unit, 3 * unit, 3 * unit, 7 * unit, unit];
        let ranges = graphics_ring_chunk_ranges_for_costs(&costs, safe);

        assert_eq!(ranges, vec![(0, 2), (2, 3), (3, 5)]);
        let mut next = 0usize;
        for (start, end) in ranges {
            assert_eq!(start, next, "chunks must preserve draw order");
            assert!(start < end);
            let bytes = costs[start..end].iter().sum::<u64>();
            assert!(bytes <= safe);
            assert!(bytes <= capacity);
            next = end;
        }
        assert_eq!(next, costs.len());
    }

    #[test]
    fn dusk_accumulation_limit_remains_ring_chunkable() {
        let safe = nexium_gpu::renderer::GRAPHICS_RING_SAFE_BATCH_BYTES;
        let conservative_draw_cost = 64 * 1024 + 255;
        let dusk_run = vec![conservative_draw_cost; 1_279];
        assert!(dusk_run.len() < MAX_ACCUMULATED_DRAWS);
        assert_eq!(
            graphics_ring_chunk_ranges_for_costs(&dusk_run, safe),
            vec![(0, dusk_run.len())]
        );

        let bounded_run = vec![conservative_draw_cost; MAX_ACCUMULATED_DRAWS];
        let ranges = graphics_ring_chunk_ranges_for_costs(&bounded_run, safe);
        assert!(
            ranges.len() > 1,
            "the ring preflight must remain authoritative"
        );
        assert_eq!(ranges.first().map(|range| range.0), Some(0));
        assert_eq!(ranges.last().map(|range| range.1), Some(bounded_run.len()));
        for (start, end) in ranges {
            assert!(bounded_run[start..end].iter().sum::<u64>() <= safe);
        }
    }

    #[test]
    fn owned_batch_chunking_moves_each_call_once_and_preserves_order() {
        #[derive(Debug, PartialEq, Eq)]
        struct NonCloneCall(u32);

        let chunks = move_into_chunks((0..7).map(NonCloneCall).collect(), &[2, 1, 3, 1]);
        assert_eq!(
            chunks,
            vec![
                vec![NonCloneCall(0), NonCloneCall(1)],
                vec![NonCloneCall(2)],
                vec![NonCloneCall(3), NonCloneCall(4), NonCloneCall(5)],
                vec![NonCloneCall(6)],
            ]
        );
    }

    #[test]
    fn prepared_draw_packet_queue_keeps_fifo_order_with_ring_and_count_limits() {
        let safe = nexium_gpu::renderer::GRAPHICS_RING_SAFE_BATCH_BYTES;
        let mut ring_queue = PreparedDrawPacketQueue::default();
        assert!(ring_queue.stage(0u32, safe / 2).is_none());
        assert!(ring_queue.stage(1u32, safe / 2).is_none());
        assert_eq!(ring_queue.stage(2u32, 1), Some(vec![0, 1]));
        assert_eq!(ring_queue.take(), vec![2]);

        let mut count_queue = PreparedDrawPacketQueue::default();
        for item in 0..PREPARED_DRAW_PACKET_MAX_BATCHES - 1 {
            assert!(count_queue.stage(item, 0).is_none());
        }
        assert_eq!(
            count_queue.stage(PREPARED_DRAW_PACKET_MAX_BATCHES - 1, 0),
            Some((0..PREPARED_DRAW_PACKET_MAX_BATCHES).collect())
        );
        assert!(count_queue.is_empty());
    }

    #[test]
    fn prepared_packetizer_reports_prior_submit_failure_once() {
        let mut packetizer = PreparedDrawPacketizer::default();
        packetizer.submit_failed = true;

        assert!(!packetizer.drain_soft());
        assert!(!packetizer.drain_soft());
        assert!(!packetizer.take_submit_completed());
        assert!(packetizer.drain_soft());
    }

    #[test]
    fn prepared_packet_gather_keeps_inline_clear_between_draws() {
        let mut queue = PreparedDrawPacketQueue::default();
        assert!(queue.stage("draw-before", 64).is_none());
        assert!(queue.stage("inline-clear", 0).is_none());
        assert!(queue.stage("draw-after", 64).is_none());

        assert_eq!(
            queue.take(),
            vec!["draw-before", "inline-clear", "draw-after"]
        );
    }

    #[test]
    fn cbuf_read_metadata_retains_static_indexed_and_more_than_thirty_two_entries() {
        let mut program = nexium_shader::IrProgram::new();
        for offset in (0..40u32).map(|word| word * 4) {
            program.emit(
                nexium_shader::IrOp::LoadCbuf {
                    binding: 6,
                    byte_offset: offset,
                },
                None,
            );
        }
        program.emit(
            nexium_shader::IrOp::LoadCbufIndexed {
                binding: 6,
                byte_offset: 0x2aa0,
                index: nexium_shader::IrValue::GprIn(37),
                address_mode: nexium_shader::CbufAddressMode::Default,
            },
            None,
        );
        let cfg = nexium_shader::Cfg {
            blocks: vec![nexium_shader::BasicBlock {
                id: 0,
                start_offset: 0,
                end_offset: 8,
                branch: nexium_shader::BranchKind::Exit,
                program,
                reg_exit: std::collections::HashMap::new(),
                pred_exit: std::collections::HashMap::new(),
                pred_phis: Vec::new(),
            }],
            unimplemented: 0,
            bindless_or_partners: Default::default(),
        };

        let reads = collect_cbuf_reads(&cfg, FRAGMENT_CBUF_BASE as u32);
        assert_eq!(reads.len(), 41);
        assert!(reads.iter().any(|read| {
            read.logical_slot == 24 && read.byte_offset == 0 && !read.is_indexed()
        }));
        assert!(reads.iter().any(|read| {
            read.logical_slot == 24
                && read.byte_offset == 0x2aa0
                && read.index_origin == nexium_gpu::bundle_cache::CbufIndexOrigin::Gpr(37)
        }));
    }

