    #[test]
    fn strict_gpu_read_follows_adjacent_noncontiguous_mappings() {
        let mut mappings = crate::gpu::GpuMappings::new();
        mappings.add(0x1000, 4, 0x2000, 1);
        mappings.add(0x1004, 4, 0x3000, 2);
        let read = |cpu: u64, out: &mut [u8]| {
            let (base, bytes): (u64, &[u8]) = if (0x2000..0x2004).contains(&cpu) {
                (0x2000, &[1, 2, 3, 4])
            } else if (0x3000..0x3004).contains(&cpu) {
                (0x3000, &[5, 6, 7, 8])
            } else {
                return false;
            };
            let offset = (cpu - base) as usize;
            let Some(source) = bytes.get(offset..offset + out.len()) else {
                return false;
            };
            out.copy_from_slice(source);
            true
        };
        assert_eq!(
            read_gpu_strict(&mappings, &read, 0x1002, 4),
            Some(vec![3, 4, 5, 6])
        );
        assert!(read_gpu_strict(&mappings, &read, 0x1006, 4).is_none());
    }

    #[test]
    fn indirect_storage_descriptors_resolve_topologically_from_actual_parent_bases() {
        let mut mappings = crate::gpu::GpuMappings::new();
        mappings.add(0x1000, 0x10, 0x5000, 1);
        mappings.add(0x2000, 0x20, 0x6000, 2);
        mappings.add(0x3000, 0x20, 0x7000, 3);

        let mut cbuf_descriptor = [0u8; 0x10];
        cbuf_descriptor[0..8].copy_from_slice(&0x2003u64.to_le_bytes());
        cbuf_descriptor[8..12].copy_from_slice(&0x80u32.to_le_bytes());
        let mut parent_data = [0u8; 0x20];
        parent_data[8..16].copy_from_slice(&0x3003u64.to_le_bytes());
        let mut child_data = [0u8; 0x20];
        child_data[7..15].copy_from_slice(&0x4005u64.to_le_bytes());
        let regions: [(u64, &[u8]); 3] = [
            (0x5000, &cbuf_descriptor),
            (0x6000, &parent_data),
            (0x7000, &child_data),
        ];
        let read = |cpu: u64, out: &mut [u8]| {
            regions.iter().any(|&(base, bytes)| {
                let Some(offset) = cpu.checked_sub(base).map(|offset| offset as usize) else {
                    return false;
                };
                let Some(source) = bytes.get(offset..offset.saturating_add(out.len())) else {
                    return false;
                };
                out.copy_from_slice(source);
                true
            })
        };

        let mut direct = nexium_shader::StorageBufferAddr::direct(0, 0, 8);
        direct.required_size = 16;
        let child = nexium_shader::StorageBufferAddr {
            cbuf_binding: 0,
            cbuf_offset: 0,
            align: 8,
            indirect: Some(nexium_shader::StorageBufferIndirection {
                parent_buffer_index: 0,
                pointer_offset: 5,
            }),
            required_size: 16,
        };
        let grandchild = nexium_shader::StorageBufferAddr {
            cbuf_binding: 0,
            cbuf_offset: 0,
            align: 8,
            indirect: Some(nexium_shader::StorageBufferIndirection {
                parent_buffer_index: 1,
                pointer_offset: 4,
            }),
            required_size: 20,
        };

        let descriptors = [direct, child, grandchild];
        assert_eq!(
            storage_pointer_source_mask(&descriptors),
            [true, true, false]
        );
        let mut actual_bases = Vec::new();
        let mut sizes = Vec::new();
        for (index, descriptor) in descriptors.into_iter().enumerate() {
            let resolved = resolve_storage_buffer_descriptor(
                index,
                descriptor,
                0x1000,
                &actual_bases,
                &mappings,
                &read,
            )
            .expect("descriptor should resolve");
            actual_bases.push(Some(resolved.actual_base));
            sizes.push(resolved.descriptor_size);
        }

        assert_eq!(actual_bases, vec![Some(0x2003), Some(0x3003), Some(0x4005)]);
        assert_eq!(sizes, vec![0x80, 16, 20]);

        let forward_reference = nexium_shader::StorageBufferAddr {
            indirect: Some(nexium_shader::StorageBufferIndirection {
                parent_buffer_index: 2,
                pointer_offset: 0,
            }),
            ..child
        };
        assert!(resolve_storage_buffer_descriptor(
            1,
            forward_reference,
            0x1000,
            &actual_bases[..1],
            &mappings,
            &read,
        )
        .is_none());
    }

    #[test]
    fn texture_snapshot_does_not_shrink_existing_vertex_range() {
        let mut snapshot = std::collections::HashMap::new();
        snapshot.insert(0x4000, std::sync::Arc::new(vec![0x5a; 0x100]));
        let mut generations = std::collections::HashMap::new();
        let mut trusted_identities = std::collections::HashMap::new();
        let mut prepared_snapshots = std::collections::HashMap::new();
        let reads = std::cell::Cell::new(0usize);
        let read = |_: u64, len: usize| {
            reads.set(reads.get() + 1);
            Some(vec![0xa5; len])
        };

        assert_eq!(
            snapshot_texture_once(
                &mut snapshot,
                &mut generations,
                &mut trusted_identities,
                &mut prepared_snapshots,
                &read,
                0x4000,
                0x10,
                None,
                None,
            ),
            0
        );
        assert_eq!(reads.get(), 0);
        assert_eq!(snapshot[&0x4000].as_slice(), &[0x5a; 0x100]);
        assert!(generations.contains_key(&(0x4000, 0x10)));
    }

    fn prepared_tic_plan_raw(gpu_va: u64) -> [u8; 32] {
        let mut raw = [0u8; 32];
        raw[0..4].copy_from_slice(&0x6014_9212u32.to_le_bytes());
        raw[4..8].copy_from_slice(&(gpu_va as u32).to_le_bytes());
        raw[8..12].copy_from_slice(&(((gpu_va >> 32) as u32 & 0xffff) | (1 << 21)).to_le_bytes());
        raw[12..16].copy_from_slice(&1u32.to_le_bytes());
        raw[16..20].copy_from_slice(&(1u32 << 23).to_le_bytes());
        raw[20..24].copy_from_slice(&(1u32 << 31).to_le_bytes());
        raw
    }

    fn prepared_tic_plan_raw_with_view(
        gpu_va: u64,
        texture_type: u32,
        base_layer: u32,
    ) -> [u8; 32] {
        let mut raw = prepared_tic_plan_raw(gpu_va);
        let mut w2 = u32::from_le_bytes(raw[8..12].try_into().unwrap());
        let mut w4 = u32::from_le_bytes(raw[16..20].try_into().unwrap());
        w2 &= !((0x1f << 16) | (0x7 << 29));
        w2 |= ((base_layer >> 3) & 0x1f) << 16;
        w2 |= ((base_layer >> 8) & 0x7) << 29;
        w4 &= !((0x7 << 16) | (0xf << 23));
        w4 |= (base_layer & 0x7) << 16;
        w4 |= (texture_type & 0xf) << 23;
        raw[8..12].copy_from_slice(&w2.to_le_bytes());
        raw[16..20].copy_from_slice(&w4.to_le_bytes());
        raw
    }

    #[test]
    fn async_texture_snapshot_uses_backing_va_and_full_storage_layers() {
        const BACKING_GPU_VA: u64 = 0x4000;
        const VIEW_GPU_VA: u64 = BACKING_GPU_VA + 4 * 32;
        const CPU_VA: u64 = 0x10_0000;
        const FULL_STORAGE_SIZE: usize = (4 + 6) * 32;

        let mut mappings = crate::gpu::GpuMappings::new();
        mappings.add(BACKING_GPU_VA, 0x1000, CPU_VA, 7);
        let raw = prepared_tic_plan_raw_with_view(VIEW_GPU_VA, 3, 4);
        let plan = derive_prepared_tic_texture_plan(raw, &mappings).expect("prepared cube view");

        assert_eq!(plan.tic.gpu_va, VIEW_GPU_VA);
        assert_eq!(plan.tic.base_layer, 4);
        assert_eq!(plan.tic.texture_type, 3);
        assert_eq!(plan.backing_gpu_va, BACKING_GPU_VA);
        assert_eq!(plan.read_size, FULL_STORAGE_SIZE);
        let cache_key = plan.cache_key.expect("mapped backing cache key");
        assert_eq!(cache_key.gpu_va, BACKING_GPU_VA);
        assert_eq!(cache_key.cpu_va, CPU_VA);
        assert_eq!(cache_key.len, FULL_STORAGE_SIZE);
        assert_eq!(cache_key.nvmap_id, 7);

        let reads = std::cell::RefCell::new(Vec::new());
        let read = |gpu_va, len| {
            reads.borrow_mut().push((gpu_va, len));
            Some(vec![0xa5; len])
        };
        let mut snapshot = std::collections::HashMap::new();
        let mut generations = std::collections::HashMap::new();
        let mut trusted_identities = std::collections::HashMap::new();
        let mut prepared_snapshots = std::collections::HashMap::new();
        let copied = snapshot_texture_once(
            &mut snapshot,
            &mut generations,
            &mut trusted_identities,
            &mut prepared_snapshots,
            &read,
            plan.backing_gpu_va,
            plan.read_size,
            None,
            None,
        );

        assert_eq!(copied, FULL_STORAGE_SIZE);
        assert_eq!(
            *reads.borrow(),
            vec![(BACKING_GPU_VA, FULL_STORAGE_SIZE); 3]
        );
        assert_eq!(
            snapshot
                .get(&BACKING_GPU_VA)
                .expect("backing snapshot")
                .len(),
            FULL_STORAGE_SIZE
        );
        assert!(!snapshot.contains_key(&VIEW_GPU_VA));
        assert!(generations.contains_key(&(BACKING_GPU_VA, FULL_STORAGE_SIZE)));
        assert!(!generations.contains_key(&(VIEW_GPU_VA, FULL_STORAGE_SIZE)));
    }

    #[test]
    fn tic_derived_plan_exact_raw_hits_without_derivation() {
        let mappings = crate::gpu::GpuMappings::new();
        let raw = prepared_tic_plan_raw_with_view(0x4000, 3, 0);
        let mut plans = FastMap::default();

        let first = memoized_prepared_tic_plan(&mut plans, 0x1000, raw, &mappings, |raw| {
            derive_prepared_tic_texture_plan(raw, &mappings)
        });
        let second = memoized_prepared_tic_plan(&mut plans, 0x1000, raw, &mappings, |_| {
            panic!("exact TIC plan hit re-derived")
        });

        assert_eq!(plans.len(), 1);
        assert_eq!(first.raw, second.raw);
        assert!(!first.cube_dependencies_resolved);
        assert!(first.cube_dependencies.is_none());
        assert!(!second.cube_dependencies_resolved);
        assert!(second.cube_dependencies.is_none());
        assert_eq!(
            first.texture.map(|texture| texture.tic.gpu_va),
            Some(0x4000)
        );
        assert_eq!(
            second.texture.map(|texture| texture.tic.gpu_va),
            Some(0x4000)
        );
    }

