    #[test]
    fn dredge_title_flushes_reuse_one_trusted_texture_validation_per_kick() {
        const DREDGE_TITLE_FLUSHES_PER_KICK: usize = 19;
        let key = TextureSnapshotCacheKey {
            mapping_epoch: 3,
            gpu_va: 0x4000,
            len: 0x26_0000,
            cpu_va: 0x10_4000,
            nvmap_id: 7,
        };
        let data = std::sync::Arc::new(vec![0x5a; 16]);
        let validations = std::cell::Cell::new(0usize);
        let mut memo = std::collections::HashMap::new();

        let first = memoized_validated_texture_snapshot_at_generations(
            &mut memo,
            Some(key),
            Some((11, 17)),
            || {
                validations.set(validations.get() + 1);
                Some((data.clone(), 11, 17, key.len, Some(13)))
            },
        )
        .expect("first validated snapshot");
        assert_eq!(
            (first.1, first.2, first.3, first.4),
            (11, 17, key.len, Some(13))
        );
        for _ in 1..DREDGE_TITLE_FLUSHES_PER_KICK {
            let reused = memoized_validated_texture_snapshot_at_generations(
                &mut memo,
                Some(key),
                Some((11, 17)),
                || panic!("exact intra-kick hit revalidated"),
            )
            .expect("reused validated snapshot");
            assert!(std::sync::Arc::ptr_eq(&first.0, &reused.0));
            assert_eq!(
                (reused.1, reused.2, reused.3, reused.4),
                (11, 17, 0, Some(13))
            );
        }
        assert_eq!(validations.get(), 1);

        let gpu_changed = memoized_validated_texture_snapshot_at_generations(
            &mut memo,
            Some(key),
            Some((12, 17)),
            || {
                validations.set(validations.get() + 1);
                Some((data.clone(), 12, 17, key.len, Some(14)))
            },
        )
        .expect("GPU write revalidated");
        assert_eq!(
            (gpu_changed.1, gpu_changed.2, gpu_changed.4),
            (12, 17, Some(14))
        );

        let commit_changed = memoized_validated_texture_snapshot_at_generations(
            &mut memo,
            Some(key),
            Some((12, 18)),
            || {
                validations.set(validations.get() + 1);
                Some((data.clone(), 12, 18, key.len, Some(15)))
            },
        )
        .expect("mapping commit revalidated");
        assert_eq!(
            (commit_changed.1, commit_changed.2, commit_changed.4),
            (12, 18, Some(15))
        );

        let changed_key = TextureSnapshotCacheKey {
            mapping_epoch: 4,
            ..key
        };
        memoized_validated_texture_snapshot_at_generations(
            &mut memo,
            Some(changed_key),
            Some((17, 23)),
            || {
                validations.set(validations.get() + 1);
                Some((data.clone(), 17, 23, changed_key.len, Some(19)))
            },
        )
        .expect("changed mapping revalidated");

        let untrusted_key = TextureSnapshotCacheKey {
            gpu_va: 0x8000,
            cpu_va: 0x10_8000,
            ..key
        };
        for _ in 0..2 {
            memoized_validated_texture_snapshot_at_generations(
                &mut memo,
                Some(untrusted_key),
                Some((23, 29)),
                || {
                    validations.set(validations.get() + 1);
                    Some((data.clone(), 23, 29, untrusted_key.len, None))
                },
            )
            .expect("untrusted snapshot remains usable");
        }

        let mut next_kick = std::collections::HashMap::new();
        memoized_validated_texture_snapshot_at_generations(
            &mut next_kick,
            Some(key),
            Some((29, 31)),
            || {
                validations.set(validations.get() + 1);
                Some((data.clone(), 29, 31, key.len, Some(31)))
            },
        )
        .expect("next kickoff revalidates");
        assert_eq!(validations.get(), 7);
    }

    #[test]
    fn kick_texture_memo_invalidates_unversioned_gpu_and_cpu_alias_writes() {
        let mut mappings = crate::gpu::GpuMappings::new();
        mappings.add(0x7abc_0000, 0x1000, 0x9000_0000, 1);
        mappings.add(0x5000_0000, 0x1000, 0x9000_0000, 1);
        let direct = TextureSnapshotCacheKey {
            mapping_epoch: mappings.mapping_epoch_for(0x7abc_0200).unwrap(),
            gpu_va: 0x7abc_0200,
            len: 0x100,
            cpu_va: 0x9000_0200,
            nvmap_id: 1,
        };
        let disjoint = TextureSnapshotCacheKey {
            gpu_va: 0x7abc_0600,
            cpu_va: 0x9000_0600,
            ..direct
        };
        let data = Arc::new(vec![0x5a; 16]);
        let mut cache = SsboSnapshotCache::default();
        fn seed(
            cache: &mut SsboSnapshotCache,
            key: TextureSnapshotCacheKey,
            data: &Arc<Vec<u8>>,
            identity: u64,
        ) {
            memoized_validated_texture_snapshot_at_generations(
                &mut cache.prepared_texture_snapshots,
                Some(key),
                Some((11, 13)),
                || Some((data.clone(), 11, 13, key.len, Some(identity))),
            )
            .unwrap();
        }

        seed(&mut cache, direct, &data, 17);
        seed(&mut cache, disjoint, &data, 19);
        cache.invalidate_gpu_write(&mappings, 0x5000_0240, 4);
        assert!(!cache.prepared_texture_snapshots.contains_key(&direct));
        assert!(cache.prepared_texture_snapshots.contains_key(&disjoint));

        seed(&mut cache, direct, &data, 23);
        cache.defer_gpu_writes(&[(direct.gpu_va + 0x40, 4)]);
        assert!(!cache.prepared_texture_snapshots.contains_key(&direct));
        assert!(cache.prepared_texture_snapshots.contains_key(&disjoint));

        seed(&mut cache, direct, &data, 29);
        cache.defer_patched_gpu_writes(&[(0x1234, direct.cpu_va + 0x80, 4)]);
        assert!(!cache.prepared_texture_snapshots.contains_key(&direct));
        assert!(cache.prepared_texture_snapshots.contains_key(&disjoint));

        seed(&mut cache, direct, &data, 31);
        cache.reset_epoch();
        assert!(cache.prepared_texture_snapshots.is_empty());
    }

    #[test]
    fn texture_snapshot_cache_reuses_all_generations_and_separates_backings() {
        let key = TextureSnapshotCacheKey {
            mapping_epoch: 1,
            gpu_va: 0x7e00_1234_4000,
            len: 4,
            cpu_va: 0x8000,
            nvmap_id: 2,
        };
        let remapped = TextureSnapshotCacheKey {
            cpu_va: 0x9000,
            ..key
        };
        let data = std::sync::Arc::new(vec![1, 2, 3, 4]);
        let mut cache = TextureSnapshotCache::new(16, 4);

        cache.insert(key, 7, 11, 13, 17, data.clone());
        let TextureSnapshotCacheLookup::Hit(hit, identity) = cache.get(key, 7, 11, 13) else {
            panic!("matching generation");
        };
        assert!(std::sync::Arc::ptr_eq(&hit, &data));
        assert_eq!(identity, 17);
        assert!(matches!(
            cache.get(remapped, 7, 11, 13),
            TextureSnapshotCacheLookup::Miss
        ));
        assert!(matches!(
            cache.get(key, 8, 11, 13),
            TextureSnapshotCacheLookup::Hit(..)
        ));
        assert!(matches!(
            cache.get(key, 8, 11, 13),
            TextureSnapshotCacheLookup::Hit(..)
        ));
        nexium_gpu::tex_invalidate::bump_region(key.gpu_va + 0x1000, 4);
        assert!(matches!(
            cache.get(key, 9, 11, 13),
            TextureSnapshotCacheLookup::Hit(..)
        ));
        nexium_gpu::tex_invalidate::bump_region(key.gpu_va, 4);
        assert!(matches!(
            cache.get(key, 10, 11, 13),
            TextureSnapshotCacheLookup::Stale
        ));

        cache.insert(key, 7, 11, 13, 19, data.clone());
        assert!(matches!(
            cache.get(key, 7, 12, 13),
            TextureSnapshotCacheLookup::Hit(..)
        ));
        cache.insert(key, 7, 12, 13, 23, data.clone());
        assert!(matches!(
            cache.get(key, 7, 12, 14),
            TextureSnapshotCacheLookup::Stale
        ));
    }

    #[test]
    fn texture_snapshot_cache_evicts_to_byte_budget() {
        let key = |gpu_va| TextureSnapshotCacheKey {
            mapping_epoch: 1,
            gpu_va,
            len: 4,
            cpu_va: gpu_va + 0x1000,
            nvmap_id: 2,
        };
        let mut cache = TextureSnapshotCache::new(6, 4);

        cache.insert(key(0x4000), 1, 2, 3, 4, std::sync::Arc::new(vec![1; 4]));
        cache.insert(key(0x5000), 1, 2, 3, 5, std::sync::Arc::new(vec![2; 4]));
        assert!(matches!(
            cache.get(key(0x4000), 1, 2, 3),
            TextureSnapshotCacheLookup::Miss
        ));
        assert!(matches!(
            cache.get(key(0x5000), 1, 2, 3),
            TextureSnapshotCacheLookup::Hit(_, 5)
        ));
        assert!(cache.bytes <= 6);
    }

    #[cfg(windows)]
    #[test]
    fn texture_host_generation_survives_overlapping_consumer_reset() {
        const CPU_VA: u64 = 0xf2_0000_0000;
        const LEN: usize = 0x1_0000;
        let ptr = nexium_memory::fastmem::commit(CPU_VA, LEN)
            .expect("write-watched texture test allocation");
        let key = TextureSnapshotCacheKey {
            mapping_epoch: 1,
            gpu_va: 0x4000,
            len: 0x2000,
            cpu_va: CPU_VA,
            nvmap_id: 2,
        };
        let host_before = take_texture_host_generation(key).expect("write watch available");
        let commit_generation = nexium_memory::fastmem::commit_generation();
        let data = std::sync::Arc::new(vec![0; key.len]);
        let mut cache = TextureSnapshotCache::new(0x10_0000, 4);
        cache.insert(key, 7, host_before, commit_generation, 11, data);

        unsafe { ptr.add(0x123).write_volatile(0x5a) };
        assert_eq!(
            nexium_memory::fastmem::take_write_watch(CPU_VA, key.len),
            nexium_memory::fastmem::WriteWatchResult::Dirty,
        );
        let host_after = take_texture_host_generation(key).expect("write watch remains available");
        assert!(host_after > host_before);
        assert!(matches!(
            cache.get(key, 7, host_after, commit_generation),
            TextureSnapshotCacheLookup::Stale
        ));

        nexium_memory::fastmem::decommit(ptr, LEN);
    }

    #[test]
    fn vertex_layout_ignores_unused_and_disabled_streams() {
        let mut engine = crate::gpu::engines::Maxwell3D::new();
        engine.dispatch_method(0x700, 0x1000 | 0x10, true);
        engine.dispatch_method(0x701, 4, true);
        engine.dispatch_method(0x702, 0x2000, true);
        engine.dispatch_method(0x704, 0x10, true);
        engine.dispatch_method(0x705, 0, true);
        engine.dispatch_method(0x706, 0x1000, true);

        let r32g32b32a32_float = (1 << 21) | (7 << 27);
        engine.dispatch_method(0x458, r32g32b32a32_float, true);
        engine.dispatch_method(0x459, r32g32b32a32_float | 1, true);
        engine.dispatch_method(0x35e, 3, true);
        let draw = engine.pending_draws.last().unwrap();

        let layout = build_vertex_layout(draw, &[0]).unwrap();
        assert_eq!(layout.attrs.len(), 1);
        assert_eq!(layout.attrs[0].location, 0);
        assert_eq!(layout.bindings.len(), 1);
        assert_eq!(layout.bindings[0].binding, 0);

        let bindings = vertex_buffer_bindings(&draw.vertex_buffers, &layout);
        assert_eq!(bindings.len(), 1);
        assert_eq!(bindings[0].addr, 0x4_0000_2000);

        let layout_with_disabled = build_vertex_layout(draw, &[0, 1]).unwrap();
        let bindings = vertex_buffer_bindings(&draw.vertex_buffers, &layout_with_disabled);
        assert_eq!(bindings.len(), 1);
        assert!(bindings.iter().all(|binding| binding.addr != 0x1000));

        let empty_layout = build_vertex_layout(draw, &[]).unwrap();
        assert!(empty_layout.attrs.is_empty());
        assert!(empty_layout.bindings.is_empty());
    }

    #[test]
    fn rejects_every_unimplemented_graphics_operation() {
        assert!(graphics_cfg_has_unimplemented(&cfg_with_unimplemented(
            nexium_shader::Opcode::BRX
        )));
        assert!(graphics_cfg_has_unimplemented(&cfg_with_unimplemented(
            nexium_shader::Opcode::TEX_b
        )));

        let mut counter_only = cfg_with_unimplemented(nexium_shader::Opcode::TMML);
        counter_only.blocks[0].program.instructions.clear();
        assert!(graphics_cfg_has_unimplemented(&counter_only));

        let mut ir_only = cfg_with_unimplemented(nexium_shader::Opcode::TXQ);
        ir_only.unimplemented = 0;
        assert!(graphics_cfg_has_unimplemented(&ir_only));

        ir_only.blocks[0].program.instructions.clear();
        assert!(!graphics_cfg_has_unimplemented(&ir_only));
    }

