    #[test]
    fn graphics_texture_view_metadata_keeps_stage_shape_and_depth_slots() {
        let sample =
            |tex_id: u32, array: bool, cube: bool, dref: bool| nexium_shader::IrOp::SampleTex {
                sample_site: None,
                tex_id,
                u: nexium_shader::IrValue::ImmF32(0.0),
                v: nexium_shader::IrValue::ImmF32(0.0),
                array: array.then_some(nexium_shader::IrValue::ImmF32(0.0)),
                volume: None,
                cube: cube.then_some(nexium_shader::IrValue::ImmF32(1.0)),
                dref: dref.then_some(nexium_shader::IrValue::ImmF32(0.5)),
                implicit_lod: true,
                lod_bias: None,
                explicit_lod: None,
                texel_offset: None,
                component: 0,
            };
        let cfg = |ops: Vec<nexium_shader::IrOp>| {
            let mut program = nexium_shader::IrProgram::new();
            for (destination, op) in ops.into_iter().enumerate() {
                program.emit(op, Some(destination as u8));
            }
            nexium_shader::Cfg {
                blocks: vec![nexium_shader::BasicBlock {
                    id: 0,
                    start_offset: 0,
                    end_offset: 8,
                    branch: nexium_shader::BranchKind::Exit,
                    program,
                    reg_exit: std::collections::HashMap::new(),
                    pred_phis: Vec::new(),
                    pred_exit: std::collections::HashMap::new(),
                }],
                unimplemented: 0,
                bindless_or_partners: std::collections::HashMap::new(),
            }
        };

        let fs_metadata =
            fragment_texture_numeric_metadata(&cfg(vec![sample(5, false, false, true)])).unwrap();
        let vs_metadata = fragment_texture_numeric_metadata(&cfg(vec![
            sample(9, true, false, false),
            sample(10, false, true, true),
            sample(11, true, true, true),
        ]))
        .unwrap();
        assert!(!fs_metadata.sampler_arrayed);
        assert!(vs_metadata.sampler_arrayed);
        assert_eq!(fs_metadata.depth_compare_2d_ids, vec![5]);
        assert_eq!(vs_metadata.depth_compare_cube_ids, vec![10]);
        assert_eq!(vs_metadata.depth_compare_cube_array_ids, vec![11]);
        assert_eq!(
            vs_metadata.image_kinds,
            vec![
                (
                    9,
                    nexium_gpu::texture_manifest::GraphicsTextureImageKind::D2Array
                ),
                (
                    10,
                    nexium_gpu::texture_manifest::GraphicsTextureImageKind::Cube
                ),
                (
                    11,
                    nexium_gpu::texture_manifest::GraphicsTextureImageKind::CubeArray
                ),
            ]
        );

        let layout = graphics_texture_layout_from_metadata(
            &fs_metadata,
            &vs_metadata,
            &[[(0, 0); GRAPHICS_CBUF_SLOTS]; 5],
            0,
            4,
            0,
            0,
            0,
            false,
            &crate::gpu::GpuMappings::new(),
            &|_, _| false,
            None,
        )
        .unwrap();
        assert!(!layout.fs_sampler_arrayed);
        assert!(layout.vs_sampler_arrayed);
        assert_eq!(layout.vs_tex_base, 1);
        assert_eq!(layout.depth_compare_2d_mask, 1 << 0);
        assert_eq!(layout.depth_compare_cube_mask, 1 << 2);
        assert_eq!(layout.depth_compare_cube_array_mask, 1 << 3);
        assert_eq!(
            nexium_gpu::texture_manifest::texture_image_kind_for_slot(&layout.manifest, 3),
            nexium_gpu::texture_manifest::GraphicsTextureImageKind::CubeArray
        );
        let normalized_view_fingerprint = texture_view_metadata_fingerprint(&layout);
        assert_ne!(normalized_view_fingerprint, 0);
        let mut rectangle_layout = layout.clone();
        rectangle_layout.manifest[0].normalized_coords = false;
        assert_ne!(
            normalized_view_fingerprint,
            texture_view_metadata_fingerprint(&rectangle_layout)
        );

        let conflict = fragment_texture_numeric_metadata(&cfg(vec![
            sample(12, false, true, false),
            sample(12, true, true, false),
        ]))
        .unwrap_err();
        assert!(conflict.contains("texture 0xc"), "{conflict}");
        assert!(conflict.contains("Cube"), "{conflict}");
        assert!(conflict.contains("CubeArray"), "{conflict}");
    }

    fn numeric_tic(
        format: nexium_gpu::texture::TicFormat,
        component_types: [nexium_gpu::texture::ComponentType; 4],
        swizzle: [nexium_gpu::texture::SwizzleSource; 4],
    ) -> nexium_gpu::texture::TicEntry {
        nexium_gpu::texture::TicEntry {
            format,
            component_types,
            swizzle,
            gpu_va: 1,
            width: 1,
            height: 1,
            block_width_log2: 0,
            block_height_log2: 0,
            block_depth_log2: 0,
            tile_width_spacing: 0,
            pitch_bytes: 0,
            is_block_linear: false,
            texture_type: 1,
            depth: 1,
            base_layer: 0,
            normalized_coords: true,
            is_srgb: false,
            is_sparse: false,
            msaa_mode: 0,
            max_mip_level: 0,
            res_min_mip_level: 0,
            res_max_mip_level: 0,
        }
    }

    #[test]
    fn render_target_alias_rejects_sparse_mipped_and_unsupported_layouts() {
        use nexium_gpu::texture::{ComponentType, SwizzleSource, TicFormat};

        let mut tic = numeric_tic(
            TicFormat::R8G8B8A8,
            [ComponentType::Unorm; 4],
            [SwizzleSource::R; 4],
        );
        tic.is_block_linear = true;
        assert!(tic_can_alias_render_target_view(&tic));

        tic.is_sparse = true;
        assert!(!tic_can_alias_render_target_view(&tic));
        tic.is_sparse = false;
        tic.max_mip_level = 1;
        assert!(tic_can_alias_render_target_view(&tic));
        tic.res_max_mip_level = 1;
        assert!(!tic_can_alias_render_target_view(&tic));
        tic.max_mip_level = 0;
        tic.res_max_mip_level = 0;
        tic.res_min_mip_level = 7;
        tic.res_max_mip_level = 15;
        assert_eq!(tic.view_base_mip(), 0);
        assert_eq!(tic.view_mip_levels(), 1);
        assert!(tic_can_alias_render_target_view(&tic));
        tic.res_min_mip_level = 0;
        tic.res_max_mip_level = 0;
        tic.max_mip_level = 1;
        tic.res_min_mip_level = 1;
        tic.res_max_mip_level = 1;
        assert!(!tic_can_alias_render_target_view(&tic));
        tic.max_mip_level = 0;
        tic.res_min_mip_level = 0;
        tic.res_max_mip_level = 0;
        tic.texture_type = 5;
        assert!(tic_can_alias_render_target_view(&tic));
        tic.depth = 2;
        assert!(!tic_can_alias_render_target_view(&tic));
        tic.depth = 1;
        tic.texture_type = 1;
        tic.base_layer = 1;
        assert!(!tic_can_alias_render_target_view(&tic));
        tic.base_layer = 0;
        tic.depth = 2;
        assert!(!tic_can_alias_render_target_view(&tic));
        tic.depth = 1;
        tic.texture_type = 2;
        tic.depth = 4;
        assert!(tic_can_alias_render_target_view(&tic));
        tic.texture_type = 4;
        tic.depth = 1;
        assert!(tic_can_alias_render_target_view(&tic));
        tic.texture_type = 3;
        assert!(!tic_can_alias_render_target_view(&tic));
        tic.texture_type = 1;
        tic.depth = 1;
        tic.is_block_linear = false;
        tic.pitch_bytes = 64;
        assert!(tic_can_alias_render_target_view(&tic));
        assert_eq!(
            super::with_tic_rt_alias_layout(RtKey::new(1, 1, 1, tic.gpu_va), &tic).layout_signature,
            2 | (64 << 8)
        );
        tic.texture_type = 4;
        assert!(!tic_can_alias_render_target_view(&tic));
        tic.texture_type = 1;
        tic.pitch_bytes = 0;
        assert!(!tic_can_alias_render_target_view(&tic));
        tic.pitch_bytes = 64;
        tic.width = 17;
        assert!(!tic_can_alias_render_target_view(&tic));
        tic.width = 1;
        tic.is_block_linear = true;
        assert!(!tic_can_alias_render_target_view(&tic));
        tic.pitch_bytes = 0;
        assert!(tic_can_alias_render_target_view(&tic));
        assert_eq!(
            super::with_tic_rt_alias_layout(RtKey::new(1, 1, 1, tic.gpu_va), &tic).layout_signature,
            1
        );
    }

    #[test]
    fn txq_only_image_kind_comes_from_resolved_tic_without_overriding_explicit_ir_kind() {
        use nexium_gpu::texture::{ComponentType, SwizzleSource, TicFormat};
        use nexium_gpu::texture_manifest::GraphicsTextureImageKind;

        let mut tic = numeric_tic(
            TicFormat::R8G8B8A8,
            [ComponentType::Unorm; 4],
            [SwizzleSource::R; 4],
        );
        for (texture_type, expected) in [
            (0, GraphicsTextureImageKind::D2),
            (1, GraphicsTextureImageKind::D2),
            (2, GraphicsTextureImageKind::D3),
            (3, GraphicsTextureImageKind::Cube),
            (4, GraphicsTextureImageKind::D2Array),
            (5, GraphicsTextureImageKind::D2Array),
            (6, GraphicsTextureImageKind::Buffer),
            (7, GraphicsTextureImageKind::D2),
            (8, GraphicsTextureImageKind::CubeArray),
        ] {
            tic.texture_type = texture_type;
            assert_eq!(tic_texture_image_kind(&tic), expected);
        }

        let shader_id = 0x44;
        tic.texture_type = 8;
        let txq_only = FragmentTextureNumericMetadata {
            texture_ids: vec![shader_id],
            descriptor_ids: vec![shader_id],
            ..Default::default()
        };
        assert_eq!(
            inferred_texture_image_kind(&txq_only, shader_id, Some(&tic)),
            GraphicsTextureImageKind::CubeArray
        );
        assert_eq!(
            inferred_texture_image_kind(&txq_only, shader_id, None),
            GraphicsTextureImageKind::D2
        );

        let explicit = FragmentTextureNumericMetadata {
            image_kinds: vec![(shader_id, GraphicsTextureImageKind::D3)],
            ..txq_only
        };
        assert_eq!(
            inferred_texture_image_kind(&explicit, shader_id, Some(&tic)),
            GraphicsTextureImageKind::D3
        );
    }

